step.action:
Call MCP tool `execute_sql` with:
      - url: {{db_url}}
      - api_key: {{service_key}}
      - sql: "SELECT seq FROM public._schema_migrations ORDER BY seq;"

check.output:
🚫 **Deployment Blocked — Database Out of Sync**

        The following migrations exist locally but are NOT applied in database:
        {{#each pending}}
        - [{{seq}}] {{description}}
        {{/each}}

        Deployment is blocked until all migrations are applied.
        This is a hard constraint to prevent runtime errors in production.
